ValidationRule.errorConditionFormula:
AND( NOT($Setup.PMC_ProcessSwitches__c.PMC_BypassValidationRule__c), $Profile.Name <> 'System Administrator', $Profile.Name <> 'API Only profile', NOT(ISCHANGED( PMC_CPQ_FlowVRByPassToggle__c )), ISCHANGED(CurrencyIsoCode ),
NOT( OR( TEXT($User.LocaleSidKey) = 'en_US' && TEXT(CurrencyIsoCode) = 'USD', TEXT($User.LocaleSidKey) = 'en_US' && TEXT(CurrencyIsoCode) = 'CAD', TEXT($User.LocaleSidKey) = 'pt_BR' && TEXT(CurrencyIsoCode) = 'USD', TEXT($User.LocaleSidKey) = 'pt_BR' && TEXT(CurrencyIsoCode) = 'BRL'
) ) )
